def main():
    print(f"Validating HAAD / DHA topics ({len(HAAD_DHA_TOPICS)})...")
    for i, t in enumerate(HAAD_DHA_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in HAAD #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in HAAD #{i+1}"
        assert len(title) > 20, f"Title too short in HAAD #{i+1}"
        assert url.startswith("https://"), f"Bad URL in HAAD #{i+1}"

    print(f"Validating PLAB / UKMLA topics ({len(PLAB_UKMLA_TOPICS)})...")
    for i, t in enumerate(PLAB_UKMLA_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in PLAB #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in PLAB #{i+1}"
        assert len(title) > 20, f"Title too short in PLAB #{i+1}"
        assert url.startswith("https://"), f"Bad URL in PLAB #{i+1}"

    print(f"Validating AMC topics ({len(AMC_TOPICS)})...")
    for i, t in enumerate(AMC_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in AMC #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in AMC #{i+1}"
        assert len(title) > 20, f"Title too short in AMC #{i+1}"
        assert url.startswith("https://"), f"Bad URL in AMC #{i+1}"

    print("All 300 topics in Part B passed validation!")

    out_path = "scripts/mega72_topics_b.py"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 72 Part B topics\n")
        f.write(f"HAAD_DHA_TOPICS = {repr(HAAD_DHA_TOPICS)}\n\n")
        f.write(f"PLAB_UKMLA_TOPICS = {repr(PLAB_UKMLA_TOPICS)}\n\n")
        f.write(f"AMC_TOPICS = {repr(AMC_TOPICS)}\n")
    print(f"Saved topics to {out_path}")

if __name__ == "__main__":
    main()
